package com.example.astar;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

/**
 * Entry point. Boots a libGDX HeadlessApplication (no rendering, no GL) and
 * runs the weighted A* tilemap pathfinder inside it.
 *
 * Usage: Main <scenario_path> <output_path>
 */
public final class Main {

    private Main() {
    }

    public static void main(String[] args) throws InterruptedException {
        if (args.length < 2) {
            System.err.println("Usage: astar <scenario_path> <output_path>");
            System.exit(2);
            return;
        }

        String scenarioPath = args[0];
        String outputPath = args[1];

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        // We drive completion ourselves; no periodic rendering is needed.
        config.updatesPerSecond = -1;

        AStarApp app = new AStarApp(scenarioPath, outputPath);
        new HeadlessApplication(app, config);

        app.awaitCompletion();
        System.exit(app.getExitCode());
    }
}

package com.example.astar;

import com.badlogic.gdx.ApplicationListener;
import com.badlogic.gdx.Gdx;

import java.util.concurrent.CountDownLatch;

/**
 * libGDX ApplicationListener that performs the whole pathfinding computation
 * once, synchronously, inside {@link #create()}, then immediately requests
 * the headless application to exit. No GL / rendering calls are made.
 */
final class AStarApp implements ApplicationListener {

    private final String scenarioPath;
    private final String outputPath;
    private final CountDownLatch done = new CountDownLatch(1);
    private volatile int exitCode = 0;

    AStarApp(String scenarioPath, String outputPath) {
        this.scenarioPath = scenarioPath;
        this.outputPath = outputPath;
    }

    @Override
    public void create() {
        try {
            Scenario scenario = Scenario.read(scenarioPath);
            Solver solver = new Solver(scenario.rows, scenario.cols, scenario.weights);
            solver.solveAll(scenario.queries, outputPath);
            exitCode = 0;
        } catch (Throwable t) {
            t.printStackTrace();
            exitCode = 1;
        } finally {
            done.countDown();
            if (Gdx.app != null) {
                Gdx.app.exit();
            }
        }
    }

    @Override
    public void resize(int width, int height) {
        // no-op: headless, no rendering surface
    }

    @Override
    public void render() {
        // no-op: all work is done once in create()
    }

    @Override
    public void pause() {
        // no-op
    }

    @Override
    public void resume() {
        // no-op
    }

    @Override
    public void dispose() {
        // no-op
    }

    void awaitCompletion() throws InterruptedException {
        done.await();
    }

    int getExitCode() {
        return exitCode;
    }
}

package com.example.astar;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Paths;

/**
 * Holds a parsed scenario: the tile-weight grid plus the list of queries.
 * The scenario file format is whitespace-separated non-negative integers:
 *
 * <pre>
 * R C
 * (R lines of C integers: tile weights, 0 = wall)
 * Q
 * (Q lines of 4 integers: SR SC GR GC)
 * </pre>
 */
final class Scenario {

    final int rows;
    final int cols;
    final int[] weights; // size rows*cols, row-major, 0 = wall
    final int[] queries; // size 4*Q: SR,SC,GR,GC per query

    private Scenario(int rows, int cols, int[] weights, int[] queries) {
        this.rows = rows;
        this.cols = cols;
        this.weights = weights;
        this.queries = queries;
    }

    static Scenario read(String path) throws IOException {
        byte[] data = Files.readAllBytes(Paths.get(path));
        IntTokenizer tok = new IntTokenizer(data);

        int rows = tok.next();
        int cols = tok.next();
        int cellCount = rows * cols;
        int[] weights = new int[cellCount];
        for (int i = 0; i < cellCount; i++) {
            weights[i] = tok.next();
        }

        int q = tok.next();
        int[] queries = new int[4 * q];
        for (int i = 0; i < queries.length; i++) {
            queries[i] = tok.next();
        }

        return new Scenario(rows, cols, weights, queries);
    }

    /** Minimal, fast whitespace-separated non-negative integer tokenizer over a byte array. */
    private static final class IntTokenizer {
        private final byte[] data;
        private int pos;

        IntTokenizer(byte[] data) {
            this.data = data;
            this.pos = 0;
        }

        int next() {
            int len = data.length;
            while (pos < len && isWhitespace(data[pos])) {
                pos++;
            }
            if (pos >= len) {
                throw new IllegalStateException("Unexpected end of scenario file while reading an integer.");
            }
            int value = 0;
            while (pos < len && data[pos] >= '0' && data[pos] <= '9') {
                value = value * 10 + (data[pos] - '0');
                pos++;
            }
            return value;
        }

        private static boolean isWhitespace(byte b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t';
        }
    }
}

